#!/usr/bin/env bash
# Relecture du chapitre 6.1 « Pourquoi tout commence par le modèle ».
# - Une seule introduction de la partie (les deux se répétaient), avec la numérotation 1 à 5 des sections expliquée ;
# - première section renommée (elle portait le titre du chapitre) ; section 1.4 redondante fondue ;
# - les « 👉 » et séparateurs « --- » fondus dans le texte ;
# - prisma.config.ts : blocs commentés supprimés (code mort ; la configuration est dans schema.prisma).
# Pas de migration. Prérequis : apply-relecture-5-3.sh.
# Usage (racine du repo) : bash apply-relecture-6-1.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/donnees/pourquoi-le-modele.mdx" 2>/dev/null | grep -qF "Une application commence par ce qu’elle manipule"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "Les couleurs d'état" "apps/web/content/docs/dev/front/styles.mdx" 2>/dev/null || { echo "lancez d'abord apply-relecture-5-3.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/donnees/pourquoi-le-modele.mdx" "prisma.config.ts")
CREATED=()
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "Une application commence par ce qu’elle manipule" "apps/web/content/docs/dev/donnees/pourquoi-le-modele.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR


python3 - <<'PY'
import base64
spec_skip_done = False
def sub(path, old, new):
    old, new = base64.b64decode(old).decode(), base64.b64decode(new).decode()
    s = open(path, encoding="utf-8").read()
    if s.count(old) == 0 and s.count(new) == 1 and spec_skip_done: return  # déjà fait par un script précédent
    assert s.count(old) == 1, (path, old[:80], s.count(old))
    open(path, "w", encoding="utf-8").write(s.replace(old, new))
sub('apps/web/content/docs/dev/donnees/pourquoi-le-modele.mdx', '',
    '')
sub('apps/web/content/docs/dev/donnees/pourquoi-le-modele.mdx', '',
