    '')
sub('apps/web/content/docs/dev/donnees/pourquoi-le-modele.mdx', '',
    '')
sub('apps/web/content/docs/dev/donnees/pourquoi-le-modele.mdx', '',
    '')
sub('apps/web/content/docs/dev/donnees/pourquoi-le-modele.mdx', '',
    '')
sub('apps/web/content/docs/dev/donnees/pourquoi-le-modele.mdx', '',
    '')
sub('prisma.config.ts', '',
    'ICAgIGRpcmVjdFVybDogcHJvY2Vzcy5lbnYuRElSRUNUX0RBVEFCQVNFX1VSTCwKICB9LAp9KQ==')
print("  édits ok (12 substitutions, 0 fichiers créés, 0 remplacés)")
